// Explota la lista de archivos en N items y clasifica subcarpeta por extensión.
// Los nombres de subcarpeta coinciden con los que crea el workflow mantix-evidencias.
const body = $input.first().json.body || $input.first().json;
const folderId = body.folderId;
const archivos = body.archivos || [];

const SUBCARPETAS = {
  INFORME: '00_INFORME_CONSOLIDADO',
  FOTOS: '02_Evidencias_Fotograficas',
  CHECKLISTS: '03_Checklists_Firmados',
  ACTAS: '04_Actas_Firmas'
};

const clasificar = (nombre, mime) => {
  const n = (nombre || '').toLowerCase();
  const m = (mime || '').toLowerCase();
  if (n.includes('acta') || n.includes('firma')) return SUBCARPETAS.ACTAS;
  if (n.includes('checklist') || n.includes('check') || n.includes('lista')) return SUBCARPETAS.CHECKLISTS;
  if (n.includes('informe') || n.includes('reporte')) return SUBCARPETAS.INFORME;
  if (m.startsWith('image/') || /\.(jpg|jpeg|png|heic|webp|gif)$/i.test(n)) return SUBCARPETAS.FOTOS;
  if (m === 'application/pdf' || n.endsWith('.pdf')) return SUBCARPETAS.INFORME;
  return SUBCARPETAS.FOTOS;
};

return archivos.map((a, i) => {
  const sub = a.subcarpeta || clasificar(a.nombre, a.mime_type);
  return {
    json: {
      index: i,
      folderId,
      subcarpeta: sub,
      fileName: a.nombre,
      mimeType: a.mime_type || 'application/octet-stream'
    },
    binary: {
      data: {
        data: a.base64,
        mimeType: a.mime_type || 'application/octet-stream',
        fileName: a.nombre
      }
    }
  };
});

// Toma el folderId de la subcarpeta encontrada y mantiene el binary data.
const input = $input.first();
const busqueda = $('Buscar subcarpeta').first().json;
const subcarpetaId = busqueda.id;
if (!subcarpetaId) {
  throw new Error(`No se encontró subcarpeta ${input.json.subcarpeta} dentro de ${input.json.folderId}`);
}
return [{
  json: { ...input.json, subcarpetaId },
  binary: input.binary
}];

// Agrega todos los uploads en un solo item de respuesta.
const items = $input.all();
const archivos = items.map(it => ({
  nombre: it.json.name || it.json.fileName,
  url: it.json.webViewLink || it.json.webContentLink || `https://drive.google.com/file/d/${it.json.id}/view`,
  file_id: it.json.id,
  subcarpeta: it.json.subcarpeta || null
}));
return [{ json: { archivos, cantidad: archivos.length } }];
